{"new_text":"def to_csv(rows, columns, header=True, delimiter=","):
    """Render a list of dicts as CSV text following RFC 4180."""
    def format_val(v):
        if v is None:
            return ""
        if isinstance(v, bool):
            return "true" if v else "false"
        return str(v)

    def escape_field(val_str):
        needs_quoting = (
            delimiter in val_str
            or '"' in val_str
            or "\n" in val_str
            or "\r" in val_str
        )
        if '"' in val_str:
            val_str = val_str.replace('"', '""')
        if needs_quoting:
            return f'"{val_str}"'
        return val_str

    lines = []
    if header:
        header_line = delimiter.join(escape_field(format_val(c)) for c in columns)
        lines.append(header_line)

    for row in rows:
        row_fields = []
        for c in columns:
            val = row.get(c)
            row_fields.append(escape_field(format_val(val)))
        lines.append(delimiter.join(row_fields))

    if not lines:
        return ""

    return "\r\n".join(lines) + "\r\n"
